from cv import *
from kf import kf_ct
from sklearn.linear_model import Ridge
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
B=['sat60','w','w_sat60']
m,e,pred=lopo(lambda: make_pipeline(StandardScaler(),Ridge(alpha=30)), B, True)
H=[]
for pid,v in t.items():
  for i in range(len(v)):
    if v[i]['core_temp'] is None: continue
    H.append(v[:i+1])
def pb(p):
  return np.mean([np.mean(np.abs(p[pids==q]-y[pids==q])) for q in sorted(set(pids))])
for ct0 in [36.9,37.1,37.3]:
  for g in [0.015,0.022,0.035]:
    kf=np.array([kf_ct(h,ct0=ct0,gamma=g*g) for h in H])
    print(ct0,g,'kf alone',round(pb(kf),3),' '.join('%.1f:%.4f'%(w,pb(pred+w*(kf-pred))) for w in [0.1,0.2,0.3,0.4]))
""]}
